//! Learning programs generated by the AI Gateway on the learner's request.
//!
//! The model only proposes content; this module decides what is accepted.
//! An answer is parsed and validated here before it is stored, and whatever
//! the model wrote is clamped to fixed limits: number of lessons, question
//! counts, text sizes. Lesson ids are assigned here, not taken from the model.
//!
//! A generated program is in one language (the one it was requested in) and
//! has three kinds of lessons: readings (Markdown with LaTeX), quizzes
//! (graded on the server; answers never leave it before an attempt) and
//! HTML5 pages, served as isolated documents like bundled artifacts.

use serde::{Deserialize, Serialize};

use crate::{LearningError, LessonDef, LessonKind, Program, Question, Quiz, Result, Text};

/// Ids of generated programs start with this prefix; bundled ids never do.
pub const PREFIX: &str = "gen-";

pub const MIN_LESSONS: usize = 3;
pub const MAX_LESSONS: usize = 10;
pub const MAX_TOPIC_CHARS: usize = 300;
const MAX_TITLE_CHARS: usize = 120;
const MAX_SUMMARY_CHARS: usize = 600;
const MAX_BRIEF_CHARS: usize = 600;
pub const MAX_READING_BYTES: usize = 48 * 1024;
pub const MAX_PAGE_BYTES: usize = 192 * 1024;
const MAX_QUESTIONS: usize = 10;
const MAX_OPTIONS: usize = 6;
const MAX_QUESTION_CHARS: usize = 1200;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Difficulty {
    Beginner,
    Intermediate,
    Advanced,
}

impl Difficulty {
    pub fn as_str(self) -> &'static str {
        match self {
            Difficulty::Beginner => "beginner",
            Difficulty::Intermediate => "intermediate",
            Difficulty::Advanced => "advanced",
        }
    }
}

/// One lesson of a generated program. Content is `None` until generated.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GeneratedLesson {
    pub id: String,
    pub kind: LessonKind,
    pub title: String,
    pub minutes: u32,
    /// What the outline said the lesson should cover; used to write it.
    pub brief: String,
    #[serde(default)]
    pub markdown: Option<String>,
    #[serde(default)]
    pub quiz: Option<Quiz>,
    #[serde(default)]
    pub html: Option<String>,
}

impl GeneratedLesson {
    pub fn is_written(&self) -> bool {
        match self.kind {
            LessonKind::Reading => self.markdown.is_some(),
            LessonKind::Quiz => self.quiz.is_some(),
            LessonKind::Page => self.html.is_some(),
            LessonKind::Artifact | LessonKind::Practice => false,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GeneratedProgram {
    pub id: String,
    pub lang: String,
    pub level: Difficulty,
    pub title: String,
    pub summary: String,
    pub lessons: Vec<GeneratedLesson>,
}

impl GeneratedProgram {
    fn text(&self, s: &str) -> Text {
        [(self.lang.clone(), s.to_owned())].into()
    }

    /// The program in the same shape as a bundled one.
    pub fn to_program(&self) -> Program {
        Program {
            id: self.id.clone(),
            version: "generated-1".into(),
            title: self.text(&self.title),
            summary: self.text(&self.summary),
            disciplines: Vec::new(),
            lessons: self
                .lessons
                .iter()
                .map(|l| LessonDef {
                    id: l.id.clone(),
                    kind: l.kind,
                    title: self.text(&l.title),
                    minutes: l.minutes,
                    content: None,
                    quiz: None,
                    artifact: None,
                    practice: None,
                    intro: Text::new(),
                    skills: Vec::new(),
                })
                .collect(),
        }
    }

    pub fn minutes(&self) -> u32 {
        self.lessons.iter().map(|l| l.minutes).sum()
    }

    fn lesson(&self, id: &str, kind: LessonKind) -> Result<&GeneratedLesson> {
        self.lessons
            .iter()
            .find(|l| l.id == id && l.kind == kind)
            .ok_or_else(|| LearningError::NotFound(format!("lesson `{id}`")))
    }

    pub fn markdown(&self, lesson: &str) -> Result<String> {
        self.lesson(lesson, LessonKind::Reading)?
            .markdown
            .clone()
            .ok_or_else(|| LearningError::NotFound(format!("text of lesson `{lesson}`")))
    }

    pub fn quiz(&self, lesson: &str) -> Result<Quiz> {
        self.lesson(lesson, LessonKind::Quiz)?
            .quiz
            .clone()
            .ok_or_else(|| LearningError::NotFound(format!("quiz of lesson `{lesson}`")))
    }

    pub fn html(&self, lesson: &str) -> Result<String> {
        self.lesson(lesson, LessonKind::Page)?
            .html
            .clone()
            .ok_or_else(|| LearningError::NotFound(format!("page of lesson `{lesson}`")))
    }
}

/// Parses the model's outline: `{title, summary, lessons: [{kind, title, minutes, brief}]}`.
pub fn parse_outline(
    id: &str,
    lang: &str,
    level: Difficulty,
    wanted: usize,
    answer: &str,
) -> Result<GeneratedProgram> {
    #[derive(Deserialize)]
    struct RawLesson {
        kind: String,
        title: String,
        #[serde(default)]
        minutes: Option<f64>,
        #[serde(default)]
        brief: String,
    }
    #[derive(Deserialize)]
    struct Raw {
        title: String,
        #[serde(default)]
        summary: String,
        lessons: Vec<RawLesson>,
    }
    let raw: Raw = serde_json::from_str(json_object(answer)?)
        .map_err(|e| invalid(format!("outline is not valid JSON: {e}")))?;
    let mut lessons = Vec::new();
    for l in raw.lessons {
        let kind = match l.kind.trim().to_ascii_lowercase().as_str() {
            "reading" | "lesson" | "text" => LessonKind::Reading,
            "quiz" | "test" => LessonKind::Quiz,
            "page" | "html" | "interactive" | "artifact" => LessonKind::Page,
            // Unknown kinds are dropped rather than guessed.
            _ => continue,
        };
        let title = clip(l.title.trim(), MAX_TITLE_CHARS);
        if title.is_empty() {
            continue;
        }
        lessons.push(GeneratedLesson {
            id: format!("l{:02}", lessons.len() + 1),
            kind,
            title,
            minutes: l.minutes.unwrap_or(10.0).clamp(2.0, 90.0) as u32,
            brief: clip(l.brief.trim(), MAX_BRIEF_CHARS),
            markdown: None,
            quiz: None,
            html: None,
        });
        if lessons.len() == wanted.clamp(MIN_LESSONS, MAX_LESSONS) {
            break;
        }
    }
    if lessons.len() < MIN_LESSONS {
        return Err(invalid(format!(
            "outline has {} usable lessons, at least {MIN_LESSONS} are needed",
            lessons.len()
        )));
    }
    let title = clip(raw.title.trim(), MAX_TITLE_CHARS);
    if title.is_empty() {
        return Err(invalid("outline has no title".into()));
    }
    Ok(GeneratedProgram {
        id: id.to_owned(),
        lang: lang.to_owned(),
        level,
        title,
        summary: clip(raw.summary.trim(), MAX_SUMMARY_CHARS),
        lessons,
    })
}

/// A reading lesson: Markdown, optionally wrapped in a ```markdown fence.
pub fn parse_reading(answer: &str) -> Result<String> {
    let text = unfence(answer, &["markdown", "md"]).trim();
    if text.chars().count() < 200 {
        return Err(invalid("lesson text is too short".into()));
    }
    if text.len() > MAX_READING_BYTES {
        return Err(invalid("lesson text is too long".into()));
    }
    Ok(text.to_owned())
}

/// A quiz: `{questions: [{text, code?, options, answer, explanation}], pass_percent?}`.
pub fn parse_quiz(answer: &str) -> Result<Quiz> {
    #[derive(Deserialize)]
    struct RawQuestion {
        text: String,
        #[serde(default)]
        code: Option<String>,
        options: Vec<String>,
        answer: usize,
        #[serde(default)]
        explanation: String,
    }
    #[derive(Deserialize)]
    struct Raw {
        questions: Vec<RawQuestion>,
        #[serde(default)]
        pass_percent: Option<u32>,
    }
    let raw: Raw = serde_json::from_str(json_object(answer)?)
        .map_err(|e| invalid(format!("quiz is not valid JSON: {e}")))?;
    let lang_free = |s: &str| -> Text { [(String::new(), s.to_owned())].into() };
    let mut questions = Vec::new();
    for q in raw.questions.into_iter().take(MAX_QUESTIONS) {
        let options: Vec<String> = q
            .options
            .iter()
            .map(|o| clip(o.trim(), MAX_QUESTION_CHARS))
            .collect();
        // A question with a broken answer key is dropped, not repaired.
        if !(2..=MAX_OPTIONS).contains(&options.len())
            || q.answer >= options.len()
            || q.text.trim().is_empty()
            || options.iter().any(String::is_empty)
        {
            continue;
        }
        questions.push(Question {
            id: format!("q{}", questions.len() + 1),
            text: lang_free(&clip(q.text.trim(), MAX_QUESTION_CHARS)),
            code: q
                .code
                .map(|c| clip(c.trim_end(), 4 * MAX_QUESTION_CHARS))
                .filter(|c| !c.trim().is_empty()),
            options: options.iter().map(|o| lang_free(o)).collect(),
            answer: q.answer,
            explanation: lang_free(&clip(q.explanation.trim(), MAX_QUESTION_CHARS)),
        });
    }
    if questions.len() < 2 {
        return Err(invalid("quiz has fewer than 2 valid questions".into()));
    }
    Ok(Quiz {
        pass_percent: raw.pass_percent.unwrap_or(70).clamp(50, 100),
        questions,
    })
}

/// An HTML5 page: a whole document, optionally wrapped in a ```html fence.
pub fn parse_page(answer: &str) -> Result<String> {
    let html = unfence(answer, &["html"]).trim();
    let lower = html.get(..html.len().min(4096)).unwrap_or(html);
    let lower = lower.to_ascii_lowercase();
    if !(lower.contains("<!doctype html") || lower.contains("<html") || lower.contains("<body")) {
        return Err(invalid("page is not an HTML document".into()));
    }
    if html.len() > MAX_PAGE_BYTES {
        return Err(invalid("page is too large".into()));
    }
    Ok(html.to_owned())
}

/// The outermost `{…}` of an answer; models like to wrap JSON in prose or fences.
fn json_object(answer: &str) -> Result<&str> {
    match (answer.find('{'), answer.rfind('}')) {
        (Some(a), Some(b)) if a < b => Ok(&answer[a..=b]),
        _ => Err(invalid("answer contains no JSON object".into())),
    }
}

/// Removes one surrounding code fence whose language is one of `langs` (or empty).
fn unfence<'a>(answer: &'a str, langs: &[&str]) -> &'a str {
    let t = answer.trim();
    let Some(rest) = t.strip_prefix("```") else {
        return t;
    };
    let (first, body) = rest.split_once('\n').unwrap_or((rest, ""));
    let lang = first.trim().to_ascii_lowercase();
    if !(lang.is_empty() || langs.contains(&lang.as_str())) {
        return t;
    }
    body.trim_end().strip_suffix("```").unwrap_or(body)
}

fn clip(s: &str, max: usize) -> String {
    s.chars().take(max).collect()
}

fn invalid(why: String) -> LearningError {
    LearningError::Invalid(why)
}

#[cfg(test)]
mod tests {
    use super::*;

    const OUTLINE: &str = r#"Here is the plan:
```json
{"title": "Graphs", "summary": "BFS and DFS",
 "lessons": [
   {"kind": "reading", "title": "What is a graph", "minutes": 12, "brief": "vertices, edges"},
   {"kind": "video", "title": "Dropped", "minutes": 5},
   {"kind": "page", "title": "BFS step by step", "minutes": 500},
   {"kind": "quiz", "title": "Check", "brief": "BFS vs DFS"},
   {"kind": "reading", "title": "   "},
   {"kind": "reading", "title": "Extra"}
 ]}
```"#;

    #[test]
    fn outline_is_validated_and_clamped() {
        let p = parse_outline("gen-1", "en", Difficulty::Beginner, 3, OUTLINE).unwrap();
        assert_eq!(p.title, "Graphs");
        let kinds: Vec<_> = p.lessons.iter().map(|l| (l.id.as_str(), l.kind)).collect();
        assert_eq!(
            kinds,
            [
                ("l01", LessonKind::Reading),
                ("l02", LessonKind::Page),
                ("l03", LessonKind::Quiz)
            ]
        );
        assert_eq!(p.lessons[1].minutes, 90);
        assert_eq!(p.lessons[2].minutes, 10);
        assert!(!p.lessons[0].is_written());
        let program = p.to_program();
        assert_eq!(
            crate::pick(&program.lessons[1].title, "ru"),
            "BFS step by step"
        );

        assert!(parse_outline("g", "en", Difficulty::Beginner, 5, "no json").is_err());
        let short = r#"{"title":"x","lessons":[{"kind":"quiz","title":"a"}]}"#;
        assert!(parse_outline("g", "en", Difficulty::Beginner, 5, short).is_err());
    }

    #[test]
    fn quizzes_drop_broken_questions() {
        let q = parse_quiz(
            r#"{"questions":[
              {"text":"2+2?","options":["3","4"],"answer":1,"explanation":"$2+2=4$"},
              {"text":"bad key","options":["a","b"],"answer":5},
              {"text":"one option","options":["a"],"answer":0},
              {"text":"BFS uses","options":["stack","queue","heap"],"answer":1}
            ], "pass_percent": 10}"#,
        )
        .unwrap();
        assert_eq!(q.questions.len(), 2);
        assert_eq!(q.questions[1].id, "q2");
        assert_eq!(q.pass_percent, 50);
        // Language-free texts are picked for any language.
        assert_eq!(crate::pick(&q.questions[0].explanation, "uz"), "$2+2=4$");
        let r = crate::grade(&q, &[("q1".into(), 1)].into(), "ru");
        assert_eq!(r.correct, 1);
        assert!(parse_quiz(r#"{"questions":[]}"#).is_err());
    }

    #[test]
    fn readings_and_pages() {
        let long = "x".repeat(300);
        assert_eq!(
            parse_reading(&format!("```markdown\n{long}\n```")).unwrap(),
            long
        );
        assert!(parse_reading("short").is_err());
        let page = parse_page("```html\n<!DOCTYPE html><html><body>hi</body></html>\n```").unwrap();
        assert!(page.starts_with("<!DOCTYPE html>") && page.ends_with("</html>"));
        assert!(parse_page("just text").is_err());
        assert!(parse_page(&format!("<html>{}", "a".repeat(MAX_PAGE_BYTES))).is_err());
    }
}
